import{_ as t,o as i,c as s,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-28（物理 / 光子学 / 紫外集成调制器）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-28-physics.md","filePath":"topics/physics/science-daily-2026-10-28-physics.md"}'),c={name:"topics/physics/science-daily-2026-10-28-physics.md"};function n(l,o,r,a,d,g){return i(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="科学日报-·-2026-10-28-物理-光子学-紫外集成调制器" tabindex="-1">科学日报 · 2026-10-28（物理 / 光子学 / 紫外集成调制器） <a class="header-anchor" href="#科学日报-·-2026-10-28-物理-光子学-紫外集成调制器" aria-label="Permalink to &quot;科学日报 · 2026-10-28（物理 / 光子学 / 紫外集成调制器）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> — 第47期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-physics</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-28-把「紫外」做成片上高速调制器——薄膜钽酸锂带宽-40-ghz、vπl-85-mv·cm" tabindex="-1">科学日报 2026-10-28：把「紫外」做成片上高速调制器——薄膜钽酸锂带宽 &gt;40 GHz、VπL 85 mV·cm <a class="header-anchor" href="#科学日报-2026-10-28-把「紫外」做成片上高速调制器——薄膜钽酸锂带宽-40-ghz、vπl-85-mv·cm" aria-label="Permalink to &quot;科学日报 2026-10-28：把「紫外」做成片上高速调制器——薄膜钽酸锂带宽 &gt;40 GHz、VπL 85 mV·cm&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ DOI: 10.1038/s41467-026-78862-6 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：<strong>紫外（UV）波段的高速集成调制</strong>是量子信息处理、便携原子钟、日盲（solar-blind）保密通信的关键，但成熟光子平台的高效工作区一直停在可见—红外；紫外的高速有源调制<strong>长期只能靠笨重的块体（bulk-crystal）晶体</strong>。既低插损、又极紧凑、还要高效率的<strong>可扩展集成方案一直是难题</strong>。</li><li>本工作：在**薄膜钽酸锂（thin-film lithium tantalate, TFLT）**平台上做出集成紫外电光调制器。</li><li>结果（实测）： <ul><li>工作波长 <strong>375 nm</strong>；</li><li><strong>集总电极仅 200 μm</strong>（极紧凑）；</li><li><strong>3 dB 电—光—电（E-O-E）带宽 &gt; 40 GHz</strong>；</li><li><strong>调制效率 VπL = 85 mV·cm</strong>（高）；</li><li><strong>电—电（E-E）带宽 &gt; 67 GHz</strong>。</li><li>作者定位：TFLT 是<strong>晶圆级兼容的有源紫外光子学</strong>的「颠覆性平台」，支撑下一代可扩展量子与通信系统。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>materials</code>）： <ol><li><strong>「把材料换掉」而不是「把器件调参」</strong> —— 紫外高速调制的瓶颈在于成熟平台（铌酸锂在可见—红外强、紫外弱）的<strong>材料窗口</strong>不够，本条换上 <strong>TFLT</strong>（钽酸锂紫外透明窗口更优 + 薄膜利于集总电极做小）→ 判据：<strong>当一个波段的器件指标被材料本征窗口锁死时，先换材料平台，而不是在原平台上微调结构。</strong> 这与 10-27「把涡旋从透镜型改腔型」、10-25「拆 SAM–钙钛矿耦合」同族——<strong>换路径（平台/机制）优于加力度（调参）。</strong></li><li><strong>「集总电极 + 小尺寸」是把调制带宽做上去的关键</strong> —— 200 μm 集总电极让 RC 时间常数足够小，才换来 &gt;40 GHz 的 E-O-E 带宽。可迁移判据：<strong>带宽受限时先看电极/寄生参数能不能压小，而不是一味加大驱动。</strong></li><li><strong>一句话定位</strong>：这条把「紫外高速调制」从块体器件推进到<strong>晶圆级可集成平台</strong>，是「片上化」在<strong>更短波长</strong>边界上的推进——与本库 <code>physics</code> 的「每个物理极限都是当前工具的极限，换工具极限就变」同构（模块一~六规律一）。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ <code>topics/materials/index.md</code> ｜ 第47期 科学板块</p></blockquote><p>关键词：科学日报第47期、薄膜钽酸锂、thin-film lithium tantalate TFLT、紫外集成电光调制器、375 nm、集总电极 200 μm、E-O-E 带宽 &gt;40 GHz、VπL 85 mV·cm、E-E 带宽 &gt;67 GHz、日盲保密通信 solar-blind、便携原子钟、量子信息处理、换材料平台而非调参、晶圆级集成、紫外光子学</p><p>关联：<code>topics/physics/index.md</code>、<code>topics/materials/index.md</code>、<code>topics/physics/science-daily-2026-10-27-physics.md</code>（等离子体涡旋腔）、<code>topics/quantum-physics/science-daily-2026-10-28-quantum.md</code>（测量诱导压缩光干涉仪）、<code>topics/ai-brain/index.md</code></p>',10)])])}const h=t(c,[["render",n]]);export{p as __pageData,h as default};
